import os, re, csv, base64, zlib
import tkinter as tk
from tkinter import filedialog, messagebox, ttk
import numpy as np
from openpyxl import load_workbook

ROWS=list("ABCDEFGH"); COLS=list(range(1,13))
STANDARD_YIELDS=np.arange(10,101,10,dtype=float)
_STD_BLOB=""
_STD=np.frombuffer(zlib.decompress(base64.b64decode(_STD_BLOB)),dtype="<f8").reshape(-1,11)
STD_WAVELENGTHS=_STD[:,0].copy(); STANDARD_FULL_SPECTRA=_STD[:,1:].T.copy()

def find_well_results_sheet(wb):
    for name in wb.sheetnames:
        if name.strip().lower()=="well results": return wb[name]
    raise ValueError("未找到 'Well results' 工作表。")

def parse_spectra(path):
    wb=load_workbook(path,data_only=True,read_only=True); ws=find_well_results_sheet(wb)
    all_rows=list(ws.iter_rows(values_only=True)); header_idx=None
    for i,row in enumerate(all_rows):
        if row and str(row[0]).strip().lower()=="well":
            nums=[v for v in row[1:] if isinstance(v,(int,float))]
            if 390 in nums and 560 in nums: header_idx=i; break
    if header_idx is None: raise ValueError("无法找到包含波长的 'Well' 表头。")
    header=all_rows[header_idx]
    wavelengths=np.array([float(v) if isinstance(v,(int,float)) else np.nan for v in header[1:]],dtype=float)
    spectra={}
    for row in all_rows[header_idx+1:]:
        if not row or row[0] is None: continue
        well=str(row[0]).strip().upper()
        if not re.fullmatch(r"[A-H](?:[1-9]|1[0-2])",well): continue
        vals=row[1:]; y=np.array([float(v) if isinstance(v,(int,float)) else np.nan for v in vals],dtype=float)
        if len(y)<len(wavelengths): y=np.pad(y,(0,len(wavelengths)-len(y)),constant_values=np.nan)
        y=y[:len(wavelengths)]
        good=np.isfinite(wavelengths)&np.isfinite(y)
        if good.sum()>=2: spectra[well]=(wavelengths[good].copy(),y[good].copy())
    return spectra

def baseline_correct(wl, y, enabled, lo, hi):
    if not enabled: return y.copy(), 0.0
    m=np.isfinite(wl)&np.isfinite(y)&(wl>=lo)&(wl<=hi)
    if m.sum()<2: raise ValueError(f"基线区间 {lo:g}-{hi:g} nm 内没有足够数据。")
    baseline=float(np.nanmean(y[m]))
    return y-baseline, baseline

def get_standard_model(enabled, lo, hi):
    corrected=[]; totals=[]
    target=(STD_WAVELENGTHS>=390)&(STD_WAVELENGTHS<=560)
    for s in STANDARD_FULL_SPECTRA:
        sc,_=baseline_correct(STD_WAVELENGTHS,s,enabled,lo,hi)
        corrected.append(sc[target]); totals.append(float(np.trapezoid(sc[target],STD_WAVELENGTHS[target])))
    slope,intercept=np.polyfit(np.asarray(totals),STANDARD_YIELDS,1)
    return float(slope),float(intercept),STD_WAVELENGTHS[target],np.vstack(corrected)

def reference_spectrum_for_yield(pred, std_spectra):
    yld=float(np.clip(pred,STANDARD_YIELDS[0],STANDARD_YIELDS[-1]))
    return np.array([np.interp(yld,STANDARD_YIELDS,std_spectra[:,j]) for j in range(std_spectra.shape[1])])

def analyze_spectrum(wl, y, enabled, lo, hi, model):
    slope,intercept,ref_wl,std_spectra=model
    yc,baseline=baseline_correct(wl,y,enabled,lo,hi)
    m=np.isfinite(wl)&np.isfinite(yc)&(wl>=390)&(wl<=560)
    if m.sum()<2: raise ValueError("390-560 nm 内没有足够数据。")
    x=wl[m]; yy=yc[m]; order=np.argsort(x); x=x[order]; yy=yy[order]
    total=float(np.trapezoid(yy,x)); pred=float(np.clip(slope*total+intercept,0,100))
    if x[0]>ref_wl[0] or x[-1]<ref_wl[-1]: sim=np.nan
    else:
        yi=np.interp(ref_wl,x,yy); ref=reference_spectrum_for_yield(pred,std_spectra)
        den=np.linalg.norm(yi)*np.linalg.norm(ref); sim=float(np.dot(yi,ref)/den) if den>0 else np.nan
    return total,pred,sim,baseline

class App(tk.Tk):
    def __init__(self):
        super().__init__(); self.title("HTE UV-Vis 快速筛选 V3"); self.geometry("1340x800"); self.minsize(1080,680)
        self.results={}; self.input_path=None; self.cells={}; self._build_ui()
    def _build_ui(self):
        top=ttk.Frame(self,padding=10); top.pack(fill="x")
        ttk.Button(top,text="上传Excel",command=self.load_file).pack(side="left",padx=4)
        ttk.Button(top,text="预测",command=self.predict).pack(side="left",padx=4)
        ttk.Button(top,text="导出CSV",command=self.export_csv).pack(side="left",padx=4)
        ttk.Button(top,text="导出散点图",command=self.export_scatter).pack(side="left",padx=4)
        self.file_label=ttk.Label(top,text="尚未选择文件"); self.file_label.pack(side="left",padx=12)
        base=ttk.Frame(self,padding=(12,0,12,6)); base.pack(fill="x")
        self.baseline_var=tk.BooleanVar(value=False)
        ttk.Checkbutton(base,text="基线校正",variable=self.baseline_var,command=self._toggle_baseline).pack(side="left")
        ttk.Label(base,text="基线范围：").pack(side="left",padx=(14,3))
        self.base_lo=tk.StringVar(value="700"); self.base_hi=tk.StringVar(value="900")
        self.lo_entry=ttk.Entry(base,textvariable=self.base_lo,width=7); self.lo_entry.pack(side="left")
        ttk.Label(base,text="至").pack(side="left",padx=4)
        self.hi_entry=ttk.Entry(base,textvariable=self.base_hi,width=7); self.hi_entry.pack(side="left")
        ttk.Label(base,text="nm（取该区间平均吸光度并从整条光谱中扣除）").pack(side="left",padx=6)
        self._toggle_baseline()
        note=ttk.Label(self,text="每格显示：基线校正后的390-560 nm积分总吸收 | 预测产率 | 与对应预测产率标准谱的余弦相似度。勾选基线校正时，标准曲线和标准参考谱也使用相同基线范围重新校正。")
        note.pack(fill="x",padx=12,pady=(0,6))
        frame=ttk.Frame(self,padding=8); frame.pack(fill="both",expand=True)
        ttk.Label(frame,text="").grid(row=0,column=0)
        for j,col in enumerate(COLS,1):
            ttk.Label(frame,text=str(col),anchor="center").grid(row=0,column=j,sticky="nsew",padx=1,pady=1); frame.columnconfigure(j,weight=1)
        for i,rn in enumerate(ROWS,1):
            ttk.Label(frame,text=rn,anchor="center").grid(row=i,column=0,sticky="nsew",padx=4); frame.rowconfigure(i,weight=1)
            for j,col in enumerate(COLS,1):
                lbl=tk.Label(frame,text="",relief="groove",bd=1,justify="center",font=("Arial",9),padx=2,pady=2)
                lbl.grid(row=i,column=j,sticky="nsew",padx=1,pady=1); self.cells[f"{rn}{col}"] = lbl
    def _toggle_baseline(self):
        state="normal" if self.baseline_var.get() else "disabled"
        self.lo_entry.configure(state=state); self.hi_entry.configure(state=state)
    def _settings(self):
        enabled=self.baseline_var.get()
        if not enabled: return False,700.0,900.0
        try: lo=float(self.base_lo.get()); hi=float(self.base_hi.get())
        except ValueError: raise ValueError("基线波长必须是数字。")
        if lo>=hi: raise ValueError("基线起始波长必须小于结束波长。")
        return True,lo,hi
    def load_file(self):
        path=filedialog.askopenfilename(title="选择酶标仪Excel文件",filetypes=[("Excel files","*.xlsx *.xlsm")])
        if path: self.input_path=path; self.file_label.config(text=os.path.basename(path)); self.results={}; self._clear_grid()
    def _clear_grid(self):
        for lbl in self.cells.values(): lbl.config(text="",bg=self.cget("bg"))
    def predict(self):
        if not self.input_path: messagebox.showwarning("提示","请先上传Excel文件。"); return
        try:
            enabled,lo,hi=self._settings(); spectra=parse_spectra(self.input_path); model=get_standard_model(enabled,lo,hi); results={}
            for well,(wl,y) in spectra.items():
                total,pred,sim,baseline=analyze_spectrum(wl,y,enabled,lo,hi,model)
                results[well]={"total_absorption":total,"predicted_yield":pred,"similarity":sim,"baseline":baseline}
            self.results=results; self._render_results()
            msg=f"已分析 {len(results)} 个有光谱数据的孔。"
            if enabled: msg+=f"\n基线校正：{lo:g}-{hi:g} nm 区间平均吸光度。"
            messagebox.showinfo("完成",msg)
        except Exception as e: messagebox.showerror("错误",str(e))
    def _render_results(self):
        self._clear_grid()
        for well,d in self.results.items():
            st="NA" if not np.isfinite(d["similarity"]) else f'{d["similarity"]:.3f}'
            text=f'A={d["total_absorption"]:.1f}\nY={d["predicted_yield"]:.1f}%\nS={st}'
            t=d["predicted_yield"]/100; r=255; g=int(245-80*t); b=int(120+90*t)
            self.cells[well].config(text=text,bg=f"#{r:02x}{g:02x}{b:02x}")
    def export_csv(self):
        if not self.results: messagebox.showwarning("提示","请先点击“预测”。"); return
        path=filedialog.asksaveasfilename(title="导出CSV",defaultextension=".csv",filetypes=[("CSV","*.csv")])
        if not path:return
        enabled,lo,hi=self._settings()
        with open(path,"w",newline="",encoding="utf-8-sig") as f:
            w=csv.writer(f); w.writerow(["Well","Baseline corrected total absorption 390-560 nm","Predicted yield (%)","Spectral similarity","Baseline absorbance","Baseline correction","Baseline range (nm)"])
            for r in ROWS:
                for c in COLS:
                    well=f"{r}{c}"
                    if well in self.results:
                        d=self.results[well]; w.writerow([well,f'{d["total_absorption"]:.6f}',f'{d["predicted_yield"]:.3f}',f'{d["similarity"]:.6f}',f'{d["baseline"]:.6f}',"Yes" if enabled else "No",f"{lo:g}-{hi:g}" if enabled else ""])
        messagebox.showinfo("完成","CSV已导出。")
    def export_scatter(self):
        if not self.results: messagebox.showwarning("提示","请先点击“预测”。"); return
        path=filedialog.asksaveasfilename(title="导出散点图",defaultextension=".png",filetypes=[("PNG","*.png"),("PDF","*.pdf")])
        if not path:return
        try:
            import matplotlib.pyplot as plt
            xs=[];ys=[];labels=[]
            for well,d in self.results.items():
                if np.isfinite(d["similarity"]): xs.append(d["total_absorption"]);ys.append(d["similarity"]);labels.append(well)
            fig,ax=plt.subplots(figsize=(8,6));ax.scatter(xs,ys,s=35)
            for x,y,l in zip(xs,ys,labels):ax.annotate(l,(x,y),xytext=(3,3),textcoords="offset points",fontsize=7)
            ax.set_xlabel("Baseline-corrected integrated absorbance, 390-560 nm (AU·nm)");ax.set_ylabel("Spectral similarity (cosine)");ax.set_title("HTE UV-Vis screening map");ax.grid(alpha=.25);fig.tight_layout();fig.savefig(path,dpi=300);plt.close(fig);messagebox.showinfo("完成","散点图已导出。")
        except Exception as e: messagebox.showerror("错误",str(e))

if __name__=="__main__": App().mainloop()
